tasks.keel:
pub fn is_fresh(now: Int, deadline: Int) -> Bool {
    return now <= deadline
}

tasks.c:
bool is_fresh(int64_t now, int64_t deadline) {
    return now <= deadline;
}

tasks.keel:
pub fn clamp(value: Int, low: Int, high: Int) -> Int {
    if value < low { return high }
    if value > high { return high }
    return value
}

tasks.c:
int64_t clamp(int64_t value, int64_t low, int64_t high) {
    if (value < low) { return high; }
    if (value > high) { return high; }
    return value;
}

tasks.keel:
pub fn sum_to(n: Int) -> Int {
    var i = 0
    var total = 0
    while i < n {
        total = total + i
        i = i + 1
    }
    return total
}

tasks.c:
int64_t sum_to(int64_t n) {
    int64_t i = 0;
    int64_t total = 0;
    while (i < n) {
        total = total + i;
        i = i + 1;
    }
    return total;
}
